def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "~": 3, "^": 4}

    def apply_operator():
        op = operators.pop()

        if op == "~":
            values[-1] = -values[-1]
            return True

        b = values.pop()
        a = values.pop()

        if op == "+":
            values.append(a + b)
        elif op == "-":
            values.append(a - b)
        elif op == "*":
            values.append(a * b)
        elif op == "^":
            if b < 0:
                return False
            values.append(pow(a, b))
        else:
            if b == 0:
                return False
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            values.append(quotient if op == "/" else a - b * quotient)

        return True

    i = 0
    expecting_operand = True

    while i < len(expr):
        char = expr[i]

        if char == " ":
            i += 1
        elif "0" <= char <= "9":
            number = 0
            while i < len(expr) and "0" <= expr[i] <= "9":
                number = number * 10 + (ord(expr[i]) - ord("0"))
                i += 1
            values.append(number)
            expecting_operand = False
        elif char == "(":
            operators.append(char)
            expecting_operand = True
            i += 1
        elif char == ")":
            while operators[-1] != "(":
                if not apply_operator():
                    return "error"
            operators.pop()
            expecting_operand = False
            i += 1
        elif char == "-" and expecting_operand:
            operators.append("~")
            i += 1
        else:
            while operators and operators[-1] != "(":
                top = operators[-1]
                if precedence[top] < precedence[char]:
                    break
                if precedence[top] == precedence[char] and char == "^":
                    break
                if not apply_operator():
                    return "error"
            operators.append(char)
            expecting_operand = True
            i += 1

    while operators:
        if not apply_operator():
            return "error"

    return values[0]
